// لائحة العمل المكتوبة — تظهر لكل الأدوار، والإدارة تحرّرها وتُحفظ مع بيانات مساحة العمل
navs.push(['policy','§','لائحة العمل']);
function policyView(){const p=db.policy&&Array.isArray(db.policy.sections)?db.policy:{version:1,updatedAt:'',updatedBy:'',sections:[]};const meta=p.updatedAt?`<small>آخر تحديث: ${stamp(p.updatedAt)}${p.updatedBy?' • '+esc(p.updatedBy):''} • إصدار ${p.version||1}</small>`:'<small>الإصدار الأساسي للائحة</small>';return card('لائحة العمل — الحضور والبريكات والتأخير',`<div class="policy-meta">${meta}</div>${p.sections.map((s,i)=>`<article class="sales-lead"><h3>${i+1}. ${esc(s.title)}</h3><p style="white-space:pre-wrap">${esc(s.body)}</p></article>`).join('')||'<p class="empty">لم تُنشر اللائحة بعد</p>'}`,role==='الإدارة'?'<button id="policyEdit">تعديل اللائحة</button>':'')}
function policyForm(){const p=db.policy&&Array.isArray(db.policy.sections)?db.policy:{sections:[]};const slots=[...p.sections.map(s=>({title:s.title,body:s.body})),{title:'',body:''},{title:'',body:''}];safeSubmit('تعديل لائحة العمل','<p>اللائحة تظهر لكل الموظفين في صفحة «لائحة العمل». اترك عنوان القسم فاضيًا لحذفه، واستخدم الخانتين الفارغتين بالأسفل لإضافة أقسام جديدة.</p>'+slots.map((s,i)=>`<h3>القسم ${i+1}</h3>${field('العنوان','pt'+i,'text',s.title)}<label>النص<textarea name="pb${i}" rows="4" maxlength="4000">${esc(s.body)}</textarea></label>`).join(''),f=>{const sections=[];for(let i=0;i<slots.length;i++){const title=String(f.get('pt'+i)||'').trim().slice(0,120),body=String(f.get('pb'+i)||'').trim().slice(0,4000);if(title&&body)sections.push({title,body})}if(!sections.length)throw Error('اكتب قسمًا واحدًا على الأقل بعنوان ونص');db.policy={sections,version:(db.policy&&db.policy.version||1)+1,updatedAt:new Date().toISOString(),updatedBy:'الإدارة'};audit('تحديث لائحة العمل — إصدار '+db.policy.version)})}
const policyPrevRender=render;render=function(){policyPrevRender();if(page==='policy'){$('#app').innerHTML=policyView();$('#policyEdit')?.addEventListener('click',policyForm)}};
